    if (n <= 1)
        return n;

    // Recursive call with the next index; the loop invariant guarantees termination.
    for (int i = 2; i <= n; ++i) {
        auto a = fib(i - 1);
        auto b = fib(i - 2);
        fib(i) = a + b;
    }
    return fib(n);
}

