int ways(int coins[], int count, int amount)
{
    // Base case: exact amount achieved.
    if (amount == 0)
        return 1;

    // No coins left or insufficient amount → no solution.
    if (amount < 0 || count == 0)
        return 0;

    // Use a loop to avoid deep recursion and keep the same result.
    int result = 0;
    for (int i = 0; i < count; ++i) {
        // Skip the current coin if it is larger than the remaining amount.
        if (coins[i] > amount)
            continue;
        // Recurse with one fewer coin and the reduced amount.
        result += ways(coins, count - 1, amount - coins[i]);
    }
    return result;
}

